{{ config(materialized='incremental', unique_key='invoice_id') }}
select i.invoice_id, i.subscription_id, i.amount_cents, i._loaded_at
from {{ ref('stg_billing__invoices') }} i
{% if is_incremental() %}
where i.subscription_id in (
    select subscription_id from {{ ref('stg_app__subscriptions') }}
    where status = 'active')
  and i._loaded_at > (select max(_loaded_at) from {{ this }})
{% endif %}

{% macro cents_to_currency(column_name, decimals=2) -%}
  round({{ column_name }} / 100.0, {{ decimals }})
{%- endmacro %}

1| {% macro watch_by_type(device_types, prefix='sec') %}
2|   {%- for t in device_types %}
3|   sum(case when device_type = '{{ t }}' then watch_seconds end)
4|     as {{ prefix }}_{{ t }}{{ ',' if loop.last }}
5|   {%- endfor %}
6| {% endmacro %}

